def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'NUM':
            advance()
            return tok[1]
        elif tok[0] == '(':
            advance()
            val = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        else:
            raise ValueError(f"Unexpected token: {tok}")

    def parse_unary():
        tok = peek()
        if tok is not None and tok[0] == '-':
            advance()
            val = parse_unary()
            return -val
        return parse_primary()

    def parse_term():
        val = parse_unary()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('*', '/'):
                advance()
                rhs = parse_unary()
                if tok[0] == '*':
                    val = val * rhs
                else:
                    # truncating division toward zero
                    sign = 1
                    if (val < 0) != (rhs < 0):
                        sign = -1
                    val = sign * (abs(val) // abs(rhs))
            else:
                break
        return val

    def parse_expr():
        val = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('+', '-'):
                advance()
                rhs = parse_term()
                if tok[0] == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

